'use strict';
// Original instructional draft. SQLite executes the explicitly portable subset;
// PostgreSQL-specific guarantees are documented separately, never inferred from it.
const C=require('../index'), questions=require('./sql-questions');
const SID='sql-fundamentals',COMMIT='e6b2f7c2b41d6261dac15825dede55e94ca35614',lessons=[];
const refs={queries:'doc/src/sgml/queries.sgml',ddl:'doc/src/sgml/ddl.sgml',dml:'doc/src/sgml/dml.sgml',comparison:'doc/src/sgml/func.sgml',tutorial:'doc/src/sgml/query.sgml'};
function add(id,comp,title,introduction,sections,code,expect,problem,steps,explanation,mistakes,takeaways,references){
 const o=C.competency(SID+'.'+comp);
 lessons.push({id,module:o.module,version:1,title,minutes:35,objectives:[{id:SID+'.'+comp,text:o.competency.text}],prerequisites:lessons.length?[lessons.at(-1).id]:[],prerequisite_note:lessons.length?'Use the previous lessons’ table, row and query vocabulary. Earlier examples remain available for reference.':'No SQL experience required. A row is one record, a column is one named attribute, and a query asks the database for a result. All examples use disposable synthetic data; running them is optional.',introduction,sections,worked:{lang:'sql',code,expect,problem,steps,explanation},mistakes,takeaways,references,reuse:[],quiz:questions[id].slice(0,3).map(q=>q.id)});
}
const section=(heading,a,b,extra={})=>({heading,paragraphs:[a,b],...extra});
add('sql-select','m1.c1','Select, filter and order a useful result',
 'A student office needs a list of eligible learners, not a dump of every stored field. SQL describes the result that is wanted. Start with a small table and a precise question: which active learners have at least 80 points, and in what order should their names appear?',[
 section('Read the clauses as a result contract','SELECT names the expressions to return. FROM identifies the input table. WHERE keeps rows for which its condition is true. ORDER BY defines the result order; LIMIT restricts the number of returned rows. A semicolon terminates a statement. Keywords are conventionally uppercase here, while single quotes delimit text values such as \'active\'.','An expression such as points >= 80 compares a column value with a number. AND requires both conditions, OR allows either, and parentheses make intended grouping explicit. Do not rely on human reading order when combining AND and OR. A query is declarative: its logical meaning does not require the database to execute each physical operation in the order you wrote it.'),
 section('Projection and sorting solve different needs','Returning name and points is projection: choosing output columns. Filtering determines which records qualify. ORDER BY points DESC places higher scores first; adding id ASC gives tied rows a unique, stable tie-breaker. Without ORDER BY, row order is unspecified even if a small test happens to return insertion order.','LIMIT 2 without a complete ordering does not reliably mean the same two learners. Offset pagination can also shift when concurrent inserts occur; stable ordering helps but is not a snapshot guarantee. Select explicit columns instead of SELECT * when an API needs a stable contract and should avoid unrelated personal fields.'),
 section('Keep values separate from executable query text','An application should supply user values through its database driver’s parameter binding, not by concatenating them into SQL. Literal values in these teaching examples are fixed synthetic fixtures. A placeholder’s spelling depends on the driver: PostgreSQL drivers may use numbered parameters while other interfaces use question marks.','Parameters represent values, not arbitrary column names or SQL clauses. A user-selected sort column must be checked against an allowlist of supported names. A correct filter alone is also not authorization: the application must enforce which learner records the signed-in user is permitted to query.')],
 "CREATE TABLE learners(id INTEGER PRIMARY KEY, name TEXT, points INTEGER, status TEXT);\nINSERT INTO learners VALUES (1,'Amina',88,'active'),(2,'Bilal',92,'paused'),(3,'Chen',88,'active'),(4,'Dara',70,'active');\nSELECT name, points FROM learners WHERE status = 'active' AND points >= 80 ORDER BY points DESC, id ASC LIMIT 2;",'Amina, 88; Chen, 88',
 'Return two qualifying active learners with deterministic tie ordering.',['Choose the output columns rather than every stored field.','Apply the active-status and minimum-points conditions together.','Sort by points and unique id before applying the limit.'],'Bilal is excluded by status and Dara by points. Amina precedes Chen because the score is tied and id is the explicit ascending tie-breaker.',
 ['A visible insertion order is not an ordering guarantee.','Concatenating a filter string can turn data into executable SQL.','Using SELECT * may expose fields the caller does not need.'],['Separate output columns, qualifying rows and result order.','Use a unique tie-breaker when a limited result must be deterministic.','Bind values through the driver and allowlist dynamic identifiers.'],['queries']);
add('sql-relations','m1.c2','Tables, keys and relationships',
 'An enrollment record must refer to a real learner and a real course. Tables organize facts; keys identify records and constraints reject invalid relationships. These ideas explain how apparently simple queries can become incorrect when their assumptions about uniqueness are false.',[
 section('Give each table a clear unit of meaning','A table has named columns and records called rows. State its grain: one row per learner, enrollment or payment. A primary key uniquely identifies a row and cannot contain NULL in PostgreSQL. It may contain one column or a combination. A name is usually a poor identifier because different people can share it and it can change.','A foreign key requires referencing values to match a referenced unique or primary key, subject to its NULL and matching rules. It does not automatically make the referencing column unique. One learner can therefore have many enrollments. A separate enrollment key, or a suitable composite unique constraint, expresses which repeated combinations are forbidden.'),
 section('Separate stored identity from business constraints','An automatically generated id is convenient but does not enforce every business rule. If one learner may enroll only once in a course, UNIQUE(learner_id, course_id) expresses that rule independently of the enrollment id. NOT NULL is needed when the relationship is mandatory; an ordinary nullable foreign key may allow a missing relationship.','A constraint is enforced by the database, including for other writers. An application-only check can race with another request. Foreign keys also have deletion/update policies such as restricting or cascading operations; choose them deliberately. Do not assume deleting a learner should delete financial history merely because cascading deletion is available.'),
 section('Know what the teaching engine does and does not establish','These examples execute a common SQL subset in isolated SQLite for repeatable outputs. PostgreSQL is the source for the production-oriented explanations. SQLite foreign-key enforcement is connection-configured, so this lesson enables it explicitly. Successful SQLite execution does not establish every PostgreSQL type, isolation or optimizer behavior.','The sample inner join uses matching ids to attach a learner name to an enrollment. A well-defined referenced key means one matching learner per enrollment. The foreign-key rule preserves references; the query still needs the correct join condition. Constraints cannot make an unrelated comparison into the right relationship.')],
 "PRAGMA foreign_keys = ON;\nCREATE TABLE learners(id INTEGER PRIMARY KEY, name TEXT NOT NULL);\nCREATE TABLE enrollments(id INTEGER PRIMARY KEY, learner_id INTEGER NOT NULL REFERENCES learners(id), course TEXT NOT NULL);\nINSERT INTO learners VALUES (1,'Amina'),(2,'Bilal');\nINSERT INTO enrollments VALUES (10,1,'SQL'),(11,1,'Git');\nSELECT e.id, l.name, e.course FROM enrollments e JOIN learners l ON l.id=e.learner_id ORDER BY e.id;",'10, Amina, SQL; 11, Amina, Git',
 'Attach the correct learner to each enrollment while allowing one learner to enroll in several courses.',['Enable fixture foreign keys and create the parent table first.','Store the relationship as learner_id rather than copying the name.','Join on the referenced identifier and order the resulting enrollments.'],'The two enrollment rows share learner_id 1 and legitimately resolve to the same learner. The fixture PRAGMA is SQLite-only setup and is not PostgreSQL SQL.',
 ['A foreign key does not mean the referencing value occurs only once.','An id column alone does not enforce one enrollment per learner/course.','SQLite constraint behavior must not be assumed identical to PostgreSQL.'],['Define the table grain before choosing keys.','Distinguish identity, uniqueness and mandatory relationships.','Make engine-specific setup explicit.'],['ddl','queries']);
add('sql-null','m1.c3','Reason correctly about missing values',
 'A missing mark is different from a mark of zero. SQL uses NULL to represent an absent or unknown value, and its comparisons follow three-valued logic. A report that ignores this distinction can silently drop learners or misstate an average.',[
 section('True, false and unknown are distinct','A comparison such as score = NULL does not test for absence. Ordinary comparisons with NULL generally produce unknown, including NULL = NULL. WHERE keeps only rows whose condition is true, so both false and unknown are rejected. Use IS NULL or IS NOT NULL to test absence directly.','NOT does not turn unknown into true. Consequently, WHERE NOT(score = 80) does not include missing scores. If the business rule includes missing values, express that explicitly with score <> 80 OR score IS NULL. AND and OR also operate on three-valued results; reason through the actual condition rather than treating unknown as a stored false value.'),
 section('Count records and recorded values deliberately','COUNT(*) counts rows. COUNT(score) counts non-NULL scores, including zero. SUM and AVG generally ignore NULL inputs; AVG(score) divides by the number of known scores rather than every row. An aggregate over no input rows returns NULL for SUM and AVG, while COUNT returns zero.','COALESCE selects the first non-NULL expression. It is useful for displaying a missing total as zero when that is the contract, but substituting zero into every missing score changes the meaning of the average. Decide whether missing means not assessed, unavailable, or genuinely zero before choosing a calculation.'),
 section('Missing values also affect membership and joins','NOT IN is particularly easy to misuse when its candidate set contains NULL: a nonmatching comparison can become unknown rather than true. For exclusion by a related record, a correlated NOT EXISTS is often clearer. NULL join keys also do not match through ordinary equality.','A LEFT JOIN can produce NULL columns for an unmatched right-side row even when that right table normally has NOT NULL columns. Distinguish this introduced absence from a real matching record with a nullable attribute. A known non-null right-side key is often the appropriate marker for testing whether a match existed.')],
 'CREATE TABLE results(id INTEGER PRIMARY KEY, score INTEGER);\nINSERT INTO results VALUES (1,80),(2,NULL),(3,0);\nSELECT COUNT(*), COUNT(score), SUM(score), AVG(score) FROM results;', '3, 2, 80, 40.0',
 'Report the population size and the average of recorded scores without turning an unassessed learner into a zero.',['Count all result rows with COUNT(*).','Count and aggregate only known score values.','Compare the recorded-score denominator with the total row count.'],'Three records exist, but only two have scores. Their sum is 80 and their average is 40. The zero is a real observation; the NULL is not.',
 ['Using = NULL does not select missing values.','COUNT(score) does not count every row.','Replacing unknown scores with zero changes a metric rather than merely formatting it.'],['Use IS NULL to test absence.','Make the aggregate denominator explicit.','Review NULL behavior in exclusion and outer-join queries.'],['comparison','queries']);
add('sql-inner-joins','m2.c1','Choose a join from the business question',
 'A support report may need tickets with assigned agents, all tickets including unassigned ones, or every possible ticket-agent pairing. Each question requires a different relationship operation. Choose a join by which records must survive, not by a habit of always typing JOIN.',[
 section('Matching and preserving are separate decisions','INNER JOIN returns pairs satisfying its ON condition. A LEFT JOIN additionally preserves every left row; when it has no matching right row, the result supplies NULL for the right columns. RIGHT JOIN reverses that preserved side, and FULL JOIN preserves unmatched rows from both sides.','A CROSS JOIN returns every pair, so four tickets and three agents yield twelve combinations. It can be appropriate for a deliberate planning grid but is usually wrong for attaching an assigned agent. Explicit aliases such as t and a distinguish columns and make the intended relationship visible.'),
 section('Put the relationship in ON','For a ticket with assigned_agent_id, the relationship is a.id = t.assigned_agent_id. Joining id to id merely because the names match can attach unrelated records. A self join uses two aliases for the same table, for example to attach an employee’s manager; it is not a special requirement to duplicate stored data.','USING(column) is concise when the named column represents the same join key on both sides. NATURAL JOIN chooses matching column names automatically, so adding an unrelated same-named column can change its behavior. Prefer an explicit reviewed condition when the schema can evolve.'),
 section('Choose the unit of the result before coding','An inner join excludes tickets without a matching agent. That is appropriate for “assigned tickets with valid agent records” but not “all tickets and their assignment status.” A left join answers the latter if tickets are on the left. The result still has one row for every matching pair, not automatically one per ticket.','An outer join is not authorization or a data repair tool. An invalid foreign key may signal a missing integrity rule; preserving its left row does not make the reference valid. Explain how unmatched records should be displayed and investigated rather than silently treating them as ordinary matches.')],
 "CREATE TABLE agents(id INTEGER PRIMARY KEY, name TEXT);\nCREATE TABLE tickets(id INTEGER PRIMARY KEY, agent_id INTEGER);\nINSERT INTO agents VALUES (1,'Amina'),(2,'Bilal');\nINSERT INTO tickets VALUES (10,1),(11,NULL),(12,2);\nSELECT t.id, a.name FROM tickets t LEFT JOIN agents a ON a.id=t.agent_id ORDER BY t.id;",'10, Amina; 11, NULL; 12, Bilal',
 'List every synthetic ticket and its agent name when assigned.',['Preserve the tickets table by placing it on the left.','Match agent_id to the agent’s primary key.','Retain and display the unmatched ticket’s NULL agent name.'],'Ticket 11 survives because this is a left join. An inner join would omit it, while a cross join would pair tickets with unrelated agents.',
 ['Matching unrelated id columns creates plausible-looking but incorrect rows.','A cross join is not an automatic lookup.','Putting the wrong table on the preserved side changes the question answered.'],['Choose the preserved population first.','Write the intended key relationship explicitly.','Expect one output row per matching pair.'],['queries']);
add('sql-outer-filters','m2.c1','Keep outer joins outer when applying filters',
 'A school wants every learner listed with any active enrollment. Filtering active enrollments after a left join seems natural, but it can remove learners who have no match. The location of a condition changes the business meaning.',[
 section('A match condition and a final filter act at different stages','ON decides which right-side records match a left row. A left join preserves the left row if no right record meets that condition. WHERE then filters the constructed joined result. A condition requiring a right-side value to equal a constant rejects NULL-extended rows when that comparison is unknown.','To list all learners with only their active enrollments attached, put the active-status restriction in ON. To list only learners with active enrollments, an inner join or a suitable WHERE filter can be correct. Neither placement is universally better; the required surviving population determines the choice.'),
 section('Handle inactive matches as well as absent matches','Adding OR e.id IS NULL to a WHERE status filter is not always equivalent to moving status into ON. A learner with only an inactive enrollment had a match before WHERE; the joined row is then rejected and no extra NULL row is created to replace it.','Filtering in ON means the inactive enrollment is not a qualifying match in the first place, so the learner survives with NULL right-side columns. This distinction matters for reports that include zero-activity accounts, products without current sales, or students without current submissions.'),
 section('Verify a query with counterexamples','A useful fixture contains a learner with an active enrollment, a learner with only inactive enrollment, and one with no enrollment at all. If a query claims to preserve everyone, assert all three appear. A test containing only active matches cannot distinguish the faulty query from the correct one.','When asking for learners with no active enrollments, the same filtered left join plus WHERE e.id IS NULL is one option; NOT EXISTS with the matching active predicate is another. Test a non-null right-side key as the marker. A nullable descriptive column does not reliably distinguish no row from a real row containing NULL.')],
 "CREATE TABLE learners(id INTEGER PRIMARY KEY, name TEXT);\nCREATE TABLE enrollments(id INTEGER PRIMARY KEY, learner_id INTEGER, status TEXT);\nINSERT INTO learners VALUES (1,'Amina'),(2,'Bilal'),(3,'Chen');\nINSERT INTO enrollments VALUES (10,1,'active'),(11,2,'paused');\nSELECT l.name, e.id FROM learners l LEFT JOIN enrollments e ON e.learner_id=l.id AND e.status='active' ORDER BY l.id;",'Amina, 10; Bilal, NULL; Chen, NULL',
 'Retain every learner while attaching only active enrollment records.',['Include active, inactive-only and unmatched learners in the fixture.','Place the active restriction in the join condition.','Inspect the preserved learner population and NULL-extended results.'],'Bilal has a stored enrollment but it is not an active match; Chen has none. Both remain because the left join preserves learners after applying its ON condition.',
 ['A right-side WHERE equality can eliminate unmatched rows.','OR right_id IS NULL cannot rescue every inactive-only case.','Testing only successful matches hides a population-loss bug.'],['Choose filter placement from the intended result.','Test inactive-only as well as completely absent relationships.','Use a non-null key to detect a missing joined row.'],['queries']);
add('sql-fanout','m2.c2','Detect row multiplication before trusting totals',
 'A learner has two enrollments and three support tickets. Joining both child tables creates six combinations for that learner. Summing a payment copied onto each combination can multiply revenue without any SQL syntax error.',[
 section('Trace the number of matches for one parent','A join emits every qualifying pair. If a parent matches two rows in one child relation and three in another independent child relation, joining both can create two times three rows. This is fan-out. Neither a foreign key nor a non-null condition makes a many-to-one relationship one-to-one.','Write down the grain of each input and desired output. One row per learner may require aggregating each child relation to learner_id before joining. One row per enrollment may intentionally repeat learner attributes, but any later aggregate must respect that repetition.'),
 section('Do not use DISTINCT as a universal repair','SELECT DISTINCT removes identical projected rows. It does not repair an incorrect relationship or guarantee the desired metric. SUM(DISTINCT amount) collapses equal numeric values even when they represent separate legitimate payments, so two independent payments of 100 can incorrectly become 100.','COUNT(DISTINCT learner_id) can be exactly right when counting unique learners. Its usefulness depends on the entity being measured. For a monetary total, compute the total at the payment grain first, or avoid the fan-out through EXISTS when the child relation is used only to test membership.'),
 section('Test cardinality assumptions with repeated children','A good fixture includes a parent with several children in both relations and two separate records with the same amount. Compare row counts before and after each join. If a result grows unexpectedly, inspect keys and multiplicities rather than adding DISTINCT until the display looks smaller.','Pre-aggregation creates a reviewed contract: at most one row per parent for that subquery. It can then be safely joined to other one-row-per-parent summaries. This is a reasoning guarantee about that query, not a promise that all joins are cheap; production performance still needs plans and representative data.')],
 'CREATE TABLE enrollments(id INTEGER PRIMARY KEY, learner_id INTEGER);\nCREATE TABLE tickets(id INTEGER PRIMARY KEY, learner_id INTEGER);\nINSERT INTO enrollments VALUES (10,1),(11,1);\nINSERT INTO tickets VALUES (20,1),(21,1),(22,1);\nSELECT COUNT(*), COUNT(DISTINCT e.id), COUNT(DISTINCT t.id) FROM enrollments e JOIN tickets t ON t.learner_id=e.learner_id;', '6, 2, 3',
 'Measure how two independent child collections multiply in a join.',['Count the two enrollment rows and three ticket rows for the same learner.','Join them on learner_id and enumerate the possible pairs.','Compare joined row count with distinct entity counts.'],'Each enrollment pairs with every ticket, yielding six rows. Distinct ids still identify two enrollments and three tickets; the pair count is a different measure.',
 ['Assuming one row per parent after a multi-child join causes double counting.','SUM(DISTINCT amount) can merge different records with equal amounts.','A smaller DISTINCT result is not proof of a correct metric.'],['Name the grain of every intermediate relation.','Trace many-to-many combinations before aggregating.','Pre-aggregate independent facts or use membership tests where appropriate.'],['queries']);
add('sql-grouping','m3.c1','Group records and filter the resulting groups',
 'An enrollment office needs total registrations by course. Returning one row for each course requires grouping the detailed records. Filtering the source records and filtering the finished course totals are related but different operations.',[
 section('GROUP BY defines the result grain','GROUP BY course places rows with the same grouping value into a group. COUNT, SUM, MIN, MAX and AVG calculate values over each group. The result is one row per grouping-key combination, not one row per original enrollment. NULL grouping values form a group rather than being discarded merely because the key is NULL.','An ordinary selected column must be grouped, aggregated, or permitted by the engine’s functional-dependency rules. For portable clear SQL, select only explicit group keys and aggregates. SQLite can accept bare columns in some aggregate queries that PostgreSQL rejects or interprets under stricter rules; do not teach that permissiveness as portable correctness.'),
 section('WHERE filters rows; HAVING filters groups','WHERE status = \'active\' removes non-active enrollment rows before aggregation. HAVING COUNT(*) >= 2 removes groups that contain fewer than two qualifying rows. Using WHERE COUNT(*) >= 2 is invalid because the group aggregate does not exist at the row-filtering stage.','Moving a row condition into HAVING can change the meaning or make a query invalid. Write the source population first, then define the grouping keys, then state any group-level threshold. Some engines allow output aliases in places others do not; repeating the aggregate expression in HAVING avoids that portability trap.'),
 section('Ordering is still an explicit final requirement','Grouping does not guarantee a sorted result. ORDER BY course explicitly orders the reported groups. If a report limits the highest totals, order by the aggregate and a deterministic key. The database may use a hash or sort internally, but neither implementation detail is a stable output contract.','Also decide what happens when no rows qualify. A grouped query with no input groups returns no rows, while a single aggregate without GROUP BY can return a count row containing zero. That distinction matters when an interface needs either an empty category list or an explicit global total.')],
 "CREATE TABLE enrollments(id INTEGER PRIMARY KEY, course TEXT, status TEXT);\nINSERT INTO enrollments VALUES (1,'SQL','active'),(2,'SQL','active'),(3,'Git','active'),(4,'Git','paused');\nSELECT course, COUNT(*) FROM enrollments WHERE status='active' GROUP BY course HAVING COUNT(*) >= 2 ORDER BY course;",'SQL, 2',
 'Show only courses with at least two active registrations.',['Filter active records before grouping.','Count records per course.','Keep only groups meeting the threshold and explicitly order them.'],'SQL has two qualifying records. Git has one after its paused enrollment is removed, so HAVING excludes that group.',
 ['WHERE cannot filter on an aggregate that has not been formed.','Grouping does not promise sorted output.','Selecting an arbitrary ungrouped descriptive field can make a query invalid or misleading.'],['Use grouping keys to define report grain.','Separate row predicates from group predicates.','Keep selected expressions consistent with the group contract.'],['queries']);
add('sql-distinct-counts','m3.c2','Count entities without confusing them with events',
 'An attendance table can contain several check-ins from the same learner. “Number of check-ins” and “number of learners who attended” are both useful metrics, but they are different questions. Correct reporting starts by naming the entity being counted.',[
 section('COUNT(*) counts records, not every business entity','A check-in record is an event. COUNT(*) over check-ins counts events, including several events from one learner. COUNT(DISTINCT learner_id) counts distinct non-NULL learner identifiers. COUNT(learner_id) counts non-NULL occurrences and still includes duplicates.','Define the reporting window before counting. If the question is unique learners per day, group by the date and count distinct learner ids within each group. Adding per-day distinct counts does not necessarily give a distinct weekly population because a learner can appear on several days.'),
 section('Preserve zero-activity categories correctly','To report every course including those without check-ins, start with courses and left join the events. COUNT(*) then counts even the preserved NULL-extended row for an empty course. COUNT(event.id), where id is a non-null event key, correctly counts only matching events.','A join can still duplicate events if another child relation is added. Count the entity key or pre-aggregate at the intended grain. DISTINCT across an entire result row is different from distinct within one aggregate, and neither choice should be applied without stating its meaning.'),
 section('Make missing identities an explicit data-quality policy','COUNT(DISTINCT learner_id) excludes NULL learner ids. If anonymous check-ins are permitted, the metric counts identified learners, not all people. COALESCE of every anonymous identity to one sentinel combines unknown individuals into a single fake learner and can distort interpretation.','A trustworthy dashboard labels its denominator and population. Prefer “identified learners with a check-in” when that is what was calculated. Constraints and input validation can require identity where business rules demand it; reporting should still explain historical missing values instead of silently inventing identities.')],
 'CREATE TABLE courses(id INTEGER PRIMARY KEY);\nCREATE TABLE visits(id INTEGER PRIMARY KEY, course_id INTEGER, learner_id INTEGER);\nINSERT INTO courses VALUES (1),(2);\nINSERT INTO visits VALUES (10,1,7),(11,1,7),(12,1,8);\nSELECT c.id, COUNT(v.id), COUNT(DISTINCT v.learner_id) FROM courses c LEFT JOIN visits v ON v.course_id=c.id GROUP BY c.id ORDER BY c.id;', '1, 3, 2; 2, 0, 0',
 'Show event counts and distinct learner counts for all courses, including a course with no events.',['Preserve courses with a left join.','Count matching non-null event keys and distinct learner keys separately.','Compare the empty course’s results with the populated course.'],'Course 1 has three events from two learners. The NULL-extended row for course 2 contributes no non-null event or learner key, giving zero for both aggregates.',
 ['Summing daily distinct populations can count one person repeatedly.','COUNT(*) after a left join includes the placeholder row.','Replacing every missing identity with one shared value creates a false entity.'],['Name the entity, event and reporting window.','Use a non-null matched key to count outer-join matches.','Label missing-identity exclusions honestly.'],['queries']);
add('sql-safe-totals','m3.c2','Build totals at the right grain',
 'Two payments of the same amount are still two payments. A finance report must preserve both without multiplying them through unrelated joins. A small pre-aggregated relation makes the grain of the total explicit and reviewable.',[
 section('Aggregate facts before attaching unrelated collections','Suppose payments and support tickets both reference a learner. Joining raw payments to tickets repeats each payment for each ticket. Instead, group payments by learner_id first, obtaining one sum per learner, and join that summary to learners. The summary’s grouping guarantees at most one row per learner key.','A derived table is a query used as an input relation and given an alias. A common table expression using WITH can name the same logical step. Neither notation inherently promises a particular materialization or performance plan; the useful property here is the defined output grain.'),
 section('Separate no payments from unknown payment amounts','SUM ignores NULL amounts. A total of zero may mean legitimate zero-valued events; a NULL total can mean no known values. After a left join to an absent summary, COALESCE(total, 0) can present a no-payment total as zero when that is the report contract.','If missing amounts are allowed, add data-quality counts instead of silently treating them as known zeros. Money examples here use integer minor units to avoid binary floating-point ambiguity. Currency, scale and rounding still need explicit business rules in a real multi-currency system.'),
 section('Verify with equal amounts and multiple children','A pair of equal payments is the counterexample to SUM(DISTINCT amount): both should contribute. A parent with two tickets exposes multiplication if raw ticket rows are joined. A parent with no payments tests the zero-display rule. These fixtures test meaning, not just syntax.','Before approving a reporting query, reconcile a small hand-calculated total with the SQL result. Check every grouping key and each join’s cardinality contract. A final DISTINCT cannot recover records already incorrectly merged by a distinct aggregate or undo an incorrect sum.')],
 'CREATE TABLE learners(id INTEGER PRIMARY KEY);\nCREATE TABLE payments(id INTEGER PRIMARY KEY, learner_id INTEGER, cents INTEGER);\nINSERT INTO learners VALUES (1),(2);\nINSERT INTO payments VALUES (10,1,100),(11,1,100);\nSELECT l.id, COALESCE(p.total,0) FROM learners l LEFT JOIN (SELECT learner_id, SUM(cents) AS total FROM payments GROUP BY learner_id) p ON p.learner_id=l.id ORDER BY l.id;', '1, 200; 2, 0',
 'Sum two equal payments correctly and include a learner with no payments.',['Group payment records by learner_id before joining.','Keep both equal-valued payments in the sum.','Use a left join and an explicit no-payment display rule.'],'Both 100-cent records contribute, so learner 1 has 200. Learner 2 has no summary match; COALESCE converts that absence to the agreed display value zero.',
 ['SUM(DISTINCT amount) removes legitimate equal-value payments.','A pre-aggregated payment total can still be repeated if later summed across a new many-side join.','Zero formatting must not conceal unknown recorded amounts.'],['Pre-aggregate independent facts at their intended grain.','Test equal-valued but distinct records.','Keep missing-data policy separate from display formatting.'],['queries']);
add('sql-safe-insert','m4.c1','Insert and update only the intended records',
 'A course office needs to create an enrollment and later change one enrollment’s status. Data-changing SQL is concise, which makes its scope easy to overlook. Practice with disposable data and state precisely which records may change before writing the statement.',[
 section('Use explicit columns and constraints when inserting','INSERT INTO enrollments(id, learner_id, status) VALUES (...) associates each supplied value with a named column. An explicit column list avoids depending on a table’s physical column order. Omitted columns use defaults or NULL where allowed, and constraints can reject invalid data.','An INSERT does not automatically establish every application permission. The service must authorize the operation and validate its business inputs. Parameter binding keeps user values separate from executable SQL; it does not replace uniqueness, foreign keys, or permission checks.'),
 section('UPDATE needs a scoped predicate','UPDATE enrollments SET status = \'active\' WHERE id = 10 changes only qualifying rows. Without WHERE it changes every row in the table. First inspect a SELECT using the intended predicate, then perform the authorized change and verify the affected row count or returned records.','A preview is not a lock: concurrent changes can occur before the update. Include the required state in the update predicate when enforcing a transition, for example WHERE id = 10 AND status = \'pending\'. If zero rows change, report the conflict or absence honestly instead of claiming success.'),
 section('Use transaction boundaries for a multi-step contract','A transaction groups changes so they commit together or roll back together according to the database’s transaction guarantees. This does not mean every possible race disappears; isolation level and the operation’s predicates still matter. Never demonstrate destructive commands against production student data.','The fixture creates its own in-memory tables, inserts fixed records, updates one authorized key, and reads the final state. Production access needs a separate connection and controlled workflow. The presence of a WHERE clause is not enough if it is the wrong predicate or accepts a user-supplied learner id without ownership validation.')],
 "CREATE TABLE enrollments(id INTEGER PRIMARY KEY, learner_id INTEGER NOT NULL, status TEXT NOT NULL);\nINSERT INTO enrollments(id,learner_id,status) VALUES (10,1,'pending'),(11,2,'pending');\nUPDATE enrollments SET status='active' WHERE id=10 AND status='pending';\nSELECT id,status FROM enrollments ORDER BY id;",'10, active; 11, pending',
 'Activate one pending enrollment without changing another learner’s record.',['Insert records with an explicit column list.','Use both the target key and expected old status in the update.','Read all fixture rows to verify the intended and untouched records.'],'Only enrollment 10 meets the complete predicate. Enrollment 11 stays pending. Real code must additionally enforce who is authorized to activate enrollment 10.',
 ['Omitting WHERE can change an entire table.','A preflight SELECT does not eliminate concurrent-state changes.','Binding input values does not establish user authorization.'],['Name INSERT columns explicitly.','Scope updates by identity and required state.','Verify the actual change and preserve multi-step consistency with transactions.'],['dml','ddl']);
add('sql-safe-delete','m4.c1','Delete deliberately and verify rollback',
 'Removing expired synthetic holds is different from removing student enrollments or financial history. DELETE removes qualifying rows, so first define the retention rule, dependencies and recovery strategy. In this lesson every operation remains inside a temporary in-memory fixture.',[
 section('DELETE changes records, not the table definition','DELETE FROM holds WHERE status = \'expired\' removes qualifying rows while retaining the table. Without WHERE it targets every row. DROP TABLE removes the table definition as well, and TRUNCATE has different engine-specific behavior and restrictions; these are not interchangeable cleanup shortcuts.','Foreign keys may reject deletion of a referenced parent or propagate a configured cascade. Read those rules before deleting. A count of selected parent rows is not necessarily the count of every related record affected by a cascade. Preserve historical records when business and retention requirements demand them.'),
 section('A transaction supports verification before commitment','BEGIN starts a transaction; COMMIT accepts its work and ROLLBACK abandons its uncommitted work. For transactional table changes in this example, deleting and then rolling back restores the rows. A backup is different from a rollback: committed changes need an appropriate recovery mechanism.','Transaction behavior is engine-specific around certain statements and external side effects. A database rollback does not unsend email or reverse a remote API call. Do not generalize a table-row demonstration into a promise that every system operation is reversible.'),
 section('Use small fixtures to test the retention boundary','Include one expired hold and one active hold. Verify that the deletion predicate targets only the expired record, then roll back and confirm both records remain. For a real timestamp-based retention policy, test equality at the cutoff, timezone interpretation and NULL timestamps.','Parameterize the cutoff value and enforce the actor’s permission. Avoid an unbounded cleanup operation merely because it worked on a two-row fixture. Production maintenance needs reviewed scope, operational limits and a recovery plan appropriate to the application; this course performs no production deletion.')],
 "CREATE TABLE holds(id INTEGER PRIMARY KEY, status TEXT);\nINSERT INTO holds VALUES (1,'expired'),(2,'active');\nBEGIN;\nDELETE FROM holds WHERE status='expired';\nROLLBACK;\nSELECT id,status FROM holds ORDER BY id;",'1, expired; 2, active',
 'Demonstrate that an uncommitted fixture deletion can be rolled back.',['Create expired and active synthetic holds.','Delete only expired records inside a transaction.','Roll back and read both records in deterministic order.'],'ROLLBACK abandons the DELETE, so both original holds appear. This proves the behavior of this transactional fixture, not the recovery of already committed production changes.',
 ['DELETE without a reviewed predicate is broad even when its syntax is valid.','A rollback cannot undo work already committed in an earlier transaction.','Database rollback does not reverse external notifications.'],['Review retention rules and referential effects.','Keep transaction and backup concepts separate.','Verify both targeted and untouched records.'],['dml']);
add('sql-subqueries-case','m4.c2','Use subqueries and CASE for precise decisions',
 'A report needs learners with no enrollment and a human-readable follow-up category. A subquery can ask whether related records exist; CASE can translate explicit conditions into a result value without changing stored data.',[
 section('EXISTS asks about matching records','A correlated subquery references a value from the outer row. EXISTS is true when its subquery returns at least one row; NOT EXISTS is true when it returns none. SELECT 1 is a conventional expression because existence, not the projected value, is what matters.','To find learners without enrollment, correlate e.learner_id = l.id. Forgetting that correlation asks whether any enrollment exists anywhere and can classify every learner identically. NOT EXISTS also avoids the NULL trap of NOT IN when the compared subquery contains missing values.'),
 section('CASE produces one expression result','CASE WHEN condition THEN value ELSE other_value END chooses the result for the first true condition. An unknown condition does not qualify. Without an ELSE, unmatched cases produce NULL. The result is a value in the query, not an update to the underlying table.','Order branches intentionally. Put a special high-priority condition before a general condition that would already match it. Choose compatible result types for the target engine rather than assuming all engines permit arbitrary mixtures. When classifying missing scores, an explicit IS NULL branch communicates the business rule.'),
 section('Different subquery shapes have different contracts','A scalar subquery is used where one value is required. It must meet the engine’s cardinality rules; PostgreSQL errors if it returns more than one row. Do not infer PostgreSQL correctness from SQLite accepting a different scalar-subquery behavior. A derived table instead supplies a relation with possibly many rows.','Subqueries are not inherently slower or faster than joins. Choose a query that states the intended result, then evaluate the production plan with representative data. Here the goal is correctness: existence should not multiply outer rows, and a display category should not silently overwrite stored values.')],
 "CREATE TABLE learners(id INTEGER PRIMARY KEY, name TEXT, score INTEGER);\nCREATE TABLE enrollments(id INTEGER PRIMARY KEY, learner_id INTEGER);\nINSERT INTO learners VALUES (1,'Amina',85),(2,'Bilal',NULL),(3,'Chen',60);\nINSERT INTO enrollments VALUES (10,1),(11,NULL);\nSELECT l.name, CASE WHEN l.score IS NULL THEN 'unassessed' WHEN l.score >= 80 THEN 'ready' ELSE 'review' END FROM learners l WHERE NOT EXISTS (SELECT 1 FROM enrollments e WHERE e.learner_id=l.id) ORDER BY l.id;",'Bilal, unassessed; Chen, review',
 'Identify learners without an enrollment and classify their score without confusing missing with low.',['Correlate the enrollment existence test to each learner id.','Handle a missing score before numeric thresholds.','Return labels without changing stored learner records.'],'Amina has an enrollment and is excluded. The enrollment with a NULL learner_id matches nobody through equality. Bilal is unassessed and Chen needs review; CASE computes labels only.',
 ['An uncorrelated existence test can accidentally classify every learner the same way.','NOT IN with a NULL candidate can produce unknown rather than true.','A CASE expression does not persist its label back to the table.'],['Correlate membership tests to the intended outer entity.','Specify missing and fallback CASE branches.','Respect scalar-subquery cardinality and engine differences.'],['queries','comparison']);
// Complementary explanations checked against the already-published final bank.
const extend=(id,...items)=>lessons.find(l=>l.id===id).sections.push(...items);
extend('sql-select',
 section('Ranges, distinct values and pagination boundaries','BETWEEN 30 AND 45 includes both endpoints. DISTINCT removes duplicate projected values: SELECT DISTINCT course returns course values, not a count. For page size 20, page 3 uses LIMIT 20 OFFSET 40 with a deterministic ordering. These clauses have fixed positions: WHERE, then ORDER BY, then LIMIT/OFFSET.','For a timestamp reporting period, prefer a half-open interval such as created_at >= start AND created_at < next_period_start, using correctly typed bound timestamps and a defined timezone. Comparing a full timestamp with a final-day midnight can exclude the remainder of that day. For frequently changing feeds, keyset pagination uses the last seen sort key and unique tie-breaker as a cursor; it avoids offset-shift duplication but is not by itself a database snapshot.'));
extend('sql-relations',
 section('Model shared entities and historical facts differently','Repeated category names can be replaced by category_id referencing a categories table, so a category rename changes one shared fact. A many-to-many relationship such as courses and instructors needs a junction table with course_id and instructor_id, normally a composite uniqueness rule, and foreign keys to both parents. A frequently changing phone number is better treated as a mutable attribute than the permanent referenced identity.','Not every repeated value is a normalization error. An order item’s unit_price_at_purchase records a historical transaction fact; replacing it with the product’s current price would rewrite the meaning of an old invoice. Use generated stable identities where appropriate, and choose RESTRICT or NO ACTION behavior when dependent history must prevent parent deletion rather than disappear through a cascade. PostgreSQL identity columns and SQLite INTEGER PRIMARY KEY generation use different mechanisms; an id omitted from INSERT needs an actual database generation/default policy.'));
extend('sql-null',
 section('Empty strings and unknown Boolean expressions','An empty string is a known text value with zero characters; it is not SQL NULL in PostgreSQL or this fixture engine. If historical data uses both representations for a missing phone, a cleanup/reporting rule may need phone IS NULL OR phone = \'\'. Do not silently extend this rule to every engine or every field without checking its contract.','Three-valued logic is not equivalent to immediately dropping every row that contains NULL anywhere. FALSE AND UNKNOWN is false, while TRUE OR UNKNOWN is true. Evaluate the combined predicate. For example, NOT(status = \'pending\' AND total > 100) is unknown for a pending row with missing total, but true for a nonpending row even when total is missing.'));
extend('sql-fanout',
 section('Choose a valid business attribution rule','A mailing list needing one row per learner should not join every saved address unless multiple deliveries are intended. Select the designated address using a valid rule, or use EXISTS if the address only establishes eligibility. Compare COUNT(*) and COUNT(DISTINCT parent_id) to detect repetition, recognizing that repetition may be intentional at a detail grain.','An order attributed to two marketing campaigns is not necessarily an invalid join. The reporting contract must specify full credit to each campaign, fractional allocation, first touch or another defensible policy. Summing overlapping campaign totals as if they were disjoint overstates overall revenue. Document the chosen measure rather than hiding overlap with arbitrary DISTINCT.'));
extend('sql-grouping',
 section('Date buckets, rounding and weighted averages','In PostgreSQL, date_trunc(\'month\', created_at) produces a monthly timestamp bucket; group by that expression to count signups by month. Timezone choice matters for timestamptz boundaries. This PostgreSQL function is not executed by the SQLite fixture. ROUND(value, 1) controls a reported decimal scale where supported; it does not change which records participate in an average.','Do not average branch averages when branches have different record counts. With 9,000 sales averaging 500 and 100 averaging 2,000, the combined mean is (9000*500 + 100*2000) / 9100, not (500+2000)/2. Compute from the original observations or carry both sum and count. HAVING COUNT(*) = COUNT(total) identifies groups where every record has a non-NULL total; COUNT(*) and COUNT(total) serve different roles.'));
extend('sql-distinct-counts',
 section('Identity rules and exactness belong to the metric','For students enrolled in both SQL and Python, first restrict to those course names, group by student_id and require COUNT(DISTINCT course)=2. Duplicate enrollments must not impersonate the two required courses. COUNT(DISTINCT status) measures statuses, not orders; COUNT(*) measures records at the current grain.','Count stable customer ids rather than raw emails when identity is available. Email case and whitespace differences may require a documented normalization rule, but arbitrary LOWER/TRIM on every identifier is not universally valid identity resolution. Approximate distinct sketches can accelerate exploratory analytics at large scale; billing or seat entitlements that require exact counts must use an exact, auditable method rather than silently inheriting an approximate dashboard metric.'));
extend('sql-safe-insert',
 section('Safe retries and atomic arithmetic need explicit rules','An import retry must use a stable business key and uniqueness constraint. PostgreSQL INSERT ... ON CONFLICT can implement a reviewed upsert policy, but a conflict handler must state which fields may be updated and avoid overwriting newer data accidentally. Idempotent retry means the same logical request does not create duplicate effects; an arbitrary newly generated id on each retry does not provide that guarantee.','Avoid reading stock=5 in two clients and then writing stock=4 twice. An atomic statement such as UPDATE products SET stock=stock-1 WHERE id=:id AND stock>=1 expresses the change against current row state; check its affected count. Placeholder syntax is illustrative and driver-specific. Use a transaction for transfers whose debit and credit must commit together, with suitable concurrency rules. Expressions such as fee=fee+100 compute from the matching row, and a subquery predicate can restrict updates to related entities.'));
extend('sql-subqueries-case',
 section('Conditional aggregation and scalar calculations','SUM(CASE WHEN status=\'paid\' THEN amount ELSE 0 END) calculates a paid-only total alongside a refunded-only total in the same result. A scalar SELECT AVG(age) can supply a comparison threshold, with its NULL policy understood. A correlated SELECT MAX(score) restricted to the same course identifies the top score per course; equality can return several tied learners.','Integer division can truncate a ratio in both PostgreSQL and SQLite. Promote an operand deliberately, for example 100.0 * converted / NULLIF(total,0), and define the zero-denominator display rule. NULLIF(total,0) returns NULL when total is zero; it avoids division by zero but does not decide whether an unavailable conversion rate should display as missing or zero. An unassessed score also needs an explicit CASE branch rather than an accidental threshold fallback.'));
